    AuditEvent = apps.get_model('core', 'AuditEvent')
    FlockIdSequence = apps.get_model('flocks', 'FlockIdSequence')
    branch_owner = dict(Branch.objects.using(db).values_list('pk', 'farm__owner_id'))
    highest = {}

    def note(user_id, branch_id, flock_id):
        number = numeric(flock_id)
        if user_id and number:
            key = (user_id, branch_id)
            highest[key] = max(highest.get(key, 0), number)

    for user_id, branch_id, flock_id in Flock.objects.using(db).values_list('user_id', 'branch_id', 'flock_id').iterator():
        note(user_id, branch_id, flock_id)
    events = AuditEvent.objects.using(db).filter(object_type='flocks.Flock').values_list('owner_id', 'before', 'after')
    for owner_id, before, after in events.iterator():
        for snapshot in (before, after):
            if not isinstance(snapshot, dict) or not snapshot.get('flock_id'):
                continue
            raw_branch = snapshot.get('branch_id')
            if raw_branch in (None, '', 'None'):
                branch_id = None
            elif str(raw_branch).isdigit() and branch_owner.get(int(raw_branch)) == owner_id:
                branch_id = int(raw_branch)
            else:
                continue  # Branch since deleted (its counter would be removed with it) or not this owner's.
            note(owner_id, branch_id, snapshot['flock_id'])
    FlockIdSequence.objects.using(db).bulk_create(
        [FlockIdSequence(user_id=user_id, branch_id=branch_id, last_number=number)
         for (user_id, branch_id), number in sorted(highest.items(), key=lambda item: (item[0][0], item[0][1] or 0))],
        batch_size=500,
    )


